function isNegativeNumber(token) {
  return /^-\d+(\.\d*)?([eE][+-]?\d+)?$/.test(token) || /^-\.\d+([eE][+-]?\d+)?$/.test(token);
}

function looksLikeOption(token) {
  return token !== '-' && token.startsWith('-');
}

export function formatUsage(prog) {
  return `usage: ${prog} [-h] --a A --b B --c C\n`;
}

export function formatHelp(prog) {
  return `${formatUsage(prog)}\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n`;
}

export function parseCommandLine(argv, scriptPath = process.argv[1]) {
  const prog = basename(scriptPath);

  for (const token of argv) {
    if (token === '-h' || token === '--help') {
      return { kind: 'help', prog };
    }
  }

  const values = { a: undefined, b: undefined, c: undefined };
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--a' || token === '--b' || token === '--c') {
      const value = argv[index + 1];

      if (
        value === undefined ||
        value === '--' ||
        (looksLikeOption(value) && !isNegativeNumber(value))
      ) {
        return {
          kind: 'error',
          prog,
          message: `argument ${token}: expected one argument`,
        };
      }

      values[token[2]] = value;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      values.a = token.slice(4);
      continue;
    }

    if (token.startsWith('--b=')) {
      values.b = token.slice(4);
      continue;
    }

    if (token.startsWith('--c=')) {
      values.c = token.slice(4);
      continue;
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    extras.push(token);
  }

  const missing = [];

  if (values.a === undefined) {
    missing.push('--a');
  }

  if (values.b === undefined) {
    missing.push('--b');
  }

  if (values.c === undefined) {
    missing.push('--c');
  }

  if (missing.length > 0) {
    return {
      kind: 'error',
      prog,
      message: `the following arguments are required: ${missing.join(', ')}`,
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      prog,
      message: `unrecognized arguments: ${extras.join(' ')}`,
    };
  }

  return { kind: 'ok', prog, values };
}

export function writeHelp(prog) {
  process.stdout.write(formatHelp(prog));
}

export function writeError(prog, message) {
  process.stderr.write(formatUsage(prog));
  process.stderr.write(`${prog}: error: ${message}\n`);
}

