function main(argv = process.argv.slice(2)) {
  const parsed = parseCommandLine(argv, process.argv[1]);

  if (parsed.kind === 'help') {
    writeHelp(parsed.prog);
    return 0;
  }

  if (parsed.kind === 'error') {
    writeError(parsed.prog, parsed.message);
    return 2;
  }

  const key1 = new PBKDF2(parsed.values.a, parsed.values.b).read(24);
  console.log(toHex(key1));

  const key2 = new PBKDF2(parsed.values.a, parsed.values.c).read(24);
  console.log(toHex(key2));

  return 0;
}

const exitCode = main();

if (exitCode !== 0) {
  process.exitCode = exitCode;
}

