export { PBKDF2, pbkdf2Read } from './pbkdf2.mjs';
export { toHex } from './bytes.mjs';

import { concatBytes, toBytes, uint32ToBigEndianBytes, xorInto } from './bytes.mjs';
import { hmacSha1 } from './hmac_sha1.mjs';

function deriveBlock(password, salt, iterations, blockIndex) {
  let u = hmacSha1(password, concatBytes(salt, uint32ToBigEndianBytes(blockIndex)));
  const output = new Uint8Array(u);

  for (let round = 1; round < iterations; round += 1) {
    u = hmacSha1(password, u);
    xorInto(output, u);
  }

  return output;
}

export class PBKDF2 {
  constructor(passphrase, salt, iterations = 1000) {
    this.password = toBytes(passphrase);
    this.salt = toBytes(salt);
    this.iterations = iterations;
    this.nextBlockIndex = 1;
    this.pending = new Uint8Array(0);
    this.pendingOffset = 0;
  }

  read(length) {
    const output = new Uint8Array(length);
    let written = 0;

    while (written < length) {
      if (this.pendingOffset >= this.pending.length) {
        this.pending = deriveBlock(
          this.password,
          this.salt,
          this.iterations,
          this.nextBlockIndex
        );
        this.pendingOffset = 0;
        this.nextBlockIndex += 1;
      }

      const remaining = length - written;
      const available = this.pending.length - this.pendingOffset;
      const chunkLength = Math.min(remaining, available);

      output.set(
        this.pending.subarray(this.pendingOffset, this.pendingOffset + chunkLength),
        written
      );

      written += chunkLength;
      this.pendingOffset += chunkLength;
    }

    return output;
  }
}

export function pbkdf2Read(passphrase, salt, length, iterations = 1000) {
  return new PBKDF2(passphrase, salt, iterations).read(length);
}

import { concatBytes, toHex, uint32ToBigEndian, utf8Encode, xorInto } from './bytes.mjs';
import { hmacSha1 } from './hmac_sha1.mjs';

export const DEFAULT_ITERATIONS = 1000;
export const DEFAULT_KEY_LENGTH = 24;
const HMAC_SHA1_LENGTH = 20;

export function pbkdf2Sha1(passwordBytes, saltBytes, iterations, keyLength) {
  const blockCount = Math.ceil(keyLength / HMAC_SHA1_LENGTH);
  const output = new Uint8Array(blockCount * HMAC_SHA1_LENGTH);

  for (let blockIndex = 1; blockIndex <= blockCount; blockIndex += 1) {
    let block = hmacSha1(
      passwordBytes,
      concatBytes([saltBytes, uint32ToBigEndian(blockIndex)]),
    );
    const accumulator = block.slice();

    for (let round = 1; round < iterations; round += 1) {
      block = hmacSha1(passwordBytes, block);
      xorInto(accumulator, block);
    }

    output.set(accumulator, (blockIndex - 1) * HMAC_SHA1_LENGTH);
  }

  return output.slice(0, keyLength);
}

export function derivePbkdf2Bytes(
  passphrase,
  salt,
  keyLength = DEFAULT_KEY_LENGTH,
  iterations = DEFAULT_ITERATIONS,
) {
  return pbkdf2Sha1(
    utf8Encode(passphrase),
    utf8Encode(salt),
    iterations,
    keyLength,
  );
}

export function derivePbkdf2Hex(
  passphrase,
  salt,
  keyLength = DEFAULT_KEY_LENGTH,
  iterations = DEFAULT_ITERATIONS,
) {
  return toHex(derivePbkdf2Bytes(passphrase, salt, keyLength, iterations));
}

export function toBytes(value) {
  if (value instanceof Uint8Array) {
    return new Uint8Array(value);
  }

  return Uint8Array.from(Buffer.from(String(value), 'utf8'));
}

export function concatBytes(...parts) {
  let totalLength = 0;

  for (const part of parts) {
    totalLength += part.length;
  }

  const output = new Uint8Array(totalLength);
  let offset = 0;

  for (const part of parts) {
    output.set(part, offset);
    offset += part.length;
  }

  return output;
}

export function xorInto(target, source) {
  for (let index = 0; index < target.length; index += 1) {
    target[index] ^= source[index];
  }

  return target;
}

export function uint32ToBigEndianBytes(value) {
  return Uint8Array.of(
    (value >>> 24) & 0xff,
    (value >>> 16) & 0xff,
    (value >>> 8) & 0xff,
    value & 0xff
  );
}

export function toHex(bytes) {
  return Buffer.from(bytes).toString('hex');
}

import { concatBytes, toBytes } from './bytes.mjs';
import { sha1 } from './sha1.mjs';

const BLOCK_SIZE = 64;

export function hmacSha1(keyInput, messageInput) {
  let key = toBytes(keyInput);
  const message = toBytes(messageInput);

  if (key.length > BLOCK_SIZE) {
    key = sha1(key);
  }

  const paddedKey = new Uint8Array(BLOCK_SIZE);
  const innerPad = new Uint8Array(BLOCK_SIZE);
  const outerPad = new Uint8Array(BLOCK_SIZE);

  paddedKey.set(key);

  for (let index = 0; index < BLOCK_SIZE; index += 1) {
    innerPad[index] = paddedKey[index] ^ 0x36;
    outerPad[index] = paddedKey[index] ^ 0x5c;
  }

  const innerDigest = sha1(concatBytes(innerPad, message));
  return sha1(concatBytes(outerPad, innerDigest));
}

import { toBytes } from './bytes.mjs';

function leftRotate(value, bits) {
  return ((value << bits) | (value >>> (32 - bits))) >>> 0;
}

export function sha1(input) {
  const message = toBytes(input);
  const paddedLength = Math.ceil((message.length + 9) / 64) * 64;
  const padded = new Uint8Array(paddedLength);
  const view = new DataView(padded.buffer);
  const schedule = new Uint32Array(80);

  padded.set(message);
  padded[message.length] = 0x80;

  const bitLength = BigInt(message.length) * 8n;
  view.setUint32(paddedLength - 8, Number((bitLength >> 32n) & 0xffffffffn));
  view.setUint32(paddedLength - 4, Number(bitLength & 0xffffffffn));

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  for (let chunkOffset = 0; chunkOffset < paddedLength; chunkOffset += 64) {
    for (let wordIndex = 0; wordIndex < 16; wordIndex += 1) {
      schedule[wordIndex] = view.getUint32(chunkOffset + (wordIndex * 4));
    }

    for (let wordIndex = 16; wordIndex < 80; wordIndex += 1) {
      schedule[wordIndex] = leftRotate(
        schedule[wordIndex - 3] ^
          schedule[wordIndex - 8] ^
          schedule[wordIndex - 14] ^
          schedule[wordIndex - 16],
        1
      );
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let index = 0; index < 80; index += 1) {
      let f;
      let k;

      if (index < 20) {
        f = (b & c) | ((~b) & d);
        k = 0x5a827999;
      } else if (index < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (index < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }

      const next = (leftRotate(a, 5) + f + e + k + schedule[index]) >>> 0;
      e = d;
      d = c;
      c = leftRotate(b, 30);
      b = a;
      a = next;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
  }

  const digest = new Uint8Array(20);
  const digestView = new DataView(digest.buffer);

  digestView.setUint32(0, h0);
  digestView.setUint32(4, h1);
  digestView.setUint32(8, h2);
  digestView.setUint32(12, h3);
  digestView.setUint32(16, h4);

  return digest;
}
